from pathlib import Path
import json
tid='DEV-PRED-A2Z-R4P3-ASTRA-PREBUILD-QUEUE-20261008-N1E138'
roots=[Path.home()/'.local/state/prediction-project-executor',Path.home()/'.local/share/prediction-project-executor']
print('ERROR_CLASS=R4P3_QUEUE_BOUNDED_DIAG')
parts=[]
for root in roots:
    if not root.exists():
        parts.append('ROOT_MISSING='+str(root)); continue
    for p in sorted(root.glob(tid+'*')):
        if p.is_file():
            try: txt=p.read_text(errors='replace')
            except Exception as e: txt='READERR:'+type(e).__name__+':'+str(e)
            parts.append('FILE='+str(p)+' TAIL='+txt[-3500:].replace('\n','\\n'))
        else:
            parts.append('PATH='+str(p)+' TYPE=DIR')
wt=Path.home()/'.local/share/prediction-project-executor/worktrees'/tid
parts.append('WORKTREE_EXISTS='+str(wt.exists()))
for rel in ['control/model_execution/patch_e106_gate.py','control/jobs/full_a2z_governed_v4.py','control/dev_checks/a2z_next_request.json']:
    p=wt/rel
    parts.append('WTFILE='+rel+' EXISTS='+str(p.exists())+' SIZE='+(str(p.stat().st_size) if p.exists() else '0'))
req=Path.home()/'.local/share/prediction-project-executor/campaigns/FULL-A2Z-LIVE-20261004-V4/requests/A2Z-V4-ASTRA-PREBUILD-DIRECT-20261008-R4P3.json'
parts.append('REQUEST_EXISTS='+str(req.exists()))
if req.exists(): parts.append('REQUEST='+req.read_text(errors='replace')[:5000].replace('\n','\\n'))
print('ERROR='+'|'.join(parts))
raise SystemExit(1)
